'use strict';
(() => {
  const $ = id => document.getElementById(id);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const labels = ['Executive Summary','Portfolio & Mission','Financial & Debt','Evidence','Risk & Options','Updates & Actions','Reports'];
  const titles = ['1. EXECUTIVE PORTFOLIO SUMMARY','PAGE 2: PORTFOLIO AND MISSION','PAGE 3: FINANCIAL PERFORMANCE AND CAPITAL CAPACITY','PAGE 4: EVIDENCE','PAGE 5: RISKS AND OPTIONS','PAGE 6: UPDATES AND ACTIONS','PAGE 7: REPORTS'];
  const paths = {
    home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-8h6v8',
    building:'M4 21V3h16v18M2 21h20M8 7h1m6 0h1M8 11h1m6 0h1M8 15h1m6 0h1M10 21v-3h4v3',
    money:'M12 2v20m5-15c-1-3-10-3-10 1 0 5 10 2 10 7 0 4-9 4-11 0',
    clock:'M12 7v6l4 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
    document:'M6 2h8l5 5v15H6zM14 2v6h5M9 12h7M9 16h7',
    chart:'M3 20h19M4 16l6-6 4 3 7-9M16 4h5v5',
    shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6zM7 12l4 4 6-8',
    bank:'m2 8 10-6 10 6zM4 10v9m5-9v9m6-9v9m5-9v9M2 22h20',
    people:'M9 6a3 3 0 1 1-6 0 3 3 0 0 1 6 0M21 6a3 3 0 1 1-6 0 3 3 0 0 1 6 0M1 21v-4c0-6 10-6 10 0v4m2 0v-4c0-6 10-6 10 0v4',
    circle:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'
  };
  const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name] || paths.document}"/></svg>`;
  let page = /^#P[1-7]$/.test(location.hash) ? location.hash.slice(1) : 'P1';
  let id = new URLSearchParams(location.search).get('assessment') || localStorage.getItem('irei:boardAssessment') || '';
  let payload = null, data = null, busyCount = 0;
  const fy = year => year ? 'FY' + year.slice(-2) : 'Unconfirmed';
  const money = value => value == null ? 'No data available' : value === 0 ? '$0' : `${value < 0 ? '-' : ''}$${(Math.abs(value)/1e6).toFixed(2)}M`;
  const ratio = value => value == null ? 'No data available' : value.toFixed(value >= .99 && value < 1 ? 3 : 2) + 'x';
  const count = value => value == null ? 'No data' : Number(value).toLocaleString('en-CA');
  const format = m => m?.value == null ? (m?.valueState === 'Not Applicable' ? 'Not applicable' : 'No data available') : m.code.includes('DSCR') ? ratio(m.value) : m.code === 'HOMES_TOTAL' ? count(m.value) : (m.code === 'CASH_AFTER_DEBT' && m.value > 0 ? '+' : '') + money(m.value);
  const metric = (code, full = false) => (full ? data.fullOperationMetrics : data.currentMetrics).find(m => m.code === code);
  const at = (code, year) => data.financialOutlook.find(p => p.year === year)?.metrics.find(m => m.code === code);
  const field = (row, name) => row.fields?.[name] ?? '';
  const rows = sheet => data.registers[sheet] || [];
  const mb = m => `<button class="metric" type="button" data-metric="${esc(m?.id || '')}">${esc(format(m))}</button>`;
  const empty = text => `<div class="empty">${esc(text || 'No data available')}</div>`;
  const table = (headers, records, cls = '') => records.length ? `<div class="table-wrap ${cls}"><table><thead><tr>${headers.map(h => `<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${records.map(r => `<tr>${r.map(c => `<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>` : empty();
  const note = text => `<div class="callout"><b>What it means</b>${esc(text)}</div>`;
  const panel = (title, body, meaning = '', ic = 'document', cls = '', detail = '') => `<section class="panel ${cls}"><h2>${icon(ic)}${esc(title)}</h2><div class="body">${body}</div>${meaning ? note(meaning) : ''}<button type="button" class="view" data-detail="${esc(detail || title)}">View details</button></section>`;
  const S = () => payload.summary;
  const F = () => payload.formatted;
  function tile(label, value, caption, ic = 'document', tone = 'teal', metricId = '') {
    const unknown = /No data|Not recorded|Not received|No date/.test(value);
    return `<${metricId ? 'button type="button"' : 'article'} class="tile tone-${esc(tone)}${unknown ? ' unknown' : ''}" ${metricId ? `data-metric="${esc(metricId)}"` : ''}><span class="icon">${icon(ic)}</span><span class="label">${esc(label)}</span><strong>${esc(value)}</strong><span class="plain-label">${page === 'P1' ? esc(label.toLowerCase()) : ''}</span><small>${esc(caption)}</small></${metricId ? 'button' : 'article'}>`;
  }
  function mt(code, label, caption, ic, full = false) {
    const m = metric(code, full); const tone = m?.value == null || code === 'RESERVE_CLOSING' ? 'amber' : code.includes('SHORTFALL') && m.value > 0 || code.includes('DSCR') && m.value < 1 ? 'red' : code === 'DEBT_SERVICE' ? 'navy' : code === 'DSCR' || code === 'CASH_SHORTFALL' ? 'green' : 'teal';
    return tile(label, format(m), caption, ic, tone, m?.id);
  }
  function tiles() {
    let list;
    if (page === 'P1') list = [tile('Buildings', count(S().buildings), 'Accepted working count', 'building'), mt('HOMES_TOTAL','Homes projected','Occupancy unconfirmed','home'), mt('NOI','Income after costs','Before loan payments','chart'), mt('DEBT_SERVICE','Loan payments','Principal + interest','bank'), mt('DSCR','Coverage','Income per $1 due','shield'), mt('RESERVE_CLOSING','Closing reserve','Permitted use unknown','money'), mt('CASH_AFTER_DEBT','Cash after loans','Projected source cash','money')];
    else if (page === 'P2') list = [tile('Properties',count(S().buildings),'Aliases retain stable IDs','building','green'),mt('HOMES_TOTAL','Homes projected','Occupancy unconfirmed','home'),tile('Homes planned',count(S().plannedHomes),'By '+fy(S().plannedBy),'building'),...['Average rent','Homes protected','Good condition','People housed'].map((l,i)=>tile(l,rows(['37_UNIT_RENT','35_AGREEMENTS','38_ASSET_CONDITION','39_MISSION_SERVICES'][i]).length?'Review records':'No data',['Actual rent rolls needed','Agreements needed','Current reports needed','Resident records needed'][i],['money','shield','building','people'][i],'amber'))];
    else if (page === 'P4') list = [tile('Source records',count(S().sourceDocuments || S().uploadedFiles),`${S().uploadedFiles} uploaded file(s)`,'document'),tile('Figures checked','Mapped','Traced to source cells','shield','green'),tile('Buildings covered',count(S().buildings),'Working portfolio scope','building'),tile('Years covered',`${fy(data.financialOutlook[0]?.year)}–${fy(data.financialOutlook.at(-1)?.year)}`,'History and source forecast','clock'),tile('Open questions',count(S().open),'Actual exception rows','document','red'),tile('Closed / accepted',count(S().resolved+S().accepted),`${S().resolved} resolved; ${S().accepted} accepted`,'shield','green'),tile('Rent rolls',S().rentRollState,'Actual evidence required','home','amber')];
    else if (page === 'P5') list = [mt('CASH_SHORTFALL','Current shortfall','Current source plan','shield'),mt('PLACEHOLDER_SUBSIDY','Placeholder subsidy','Annual future source assumption','money',true),tile('Forward below 1x',`${S().belowOne} of ${S().forwardPeriods}`,'Full precision coverage','chart','red'),tile('New development payments',F().newPayments,'Annual service at full operation','bank'),mt('RESERVE_CLOSING','Closing reserve','Permitted use unknown','money'),tile('Mortgage terms','Not established','Current statements needed','clock','amber'),mt('SHORTFALL_EX_PLACEHOLDER','No-subsidy '+fy(S().fullYear),'Annual cash gap','shield',true)];
    else if (page === 'P6') list = [tile('Current record',data.context.sourceVersion || 'Working','Original inputs retained','document'),tile('Reporting year',fy(S().currentYear),metric('NOI')?.scenario || 'Source plan','clock'),tile('Open exceptions',count(S().open),'Register status retained','document','red'),tile('Actions open',rows('48_ACTIONS').length ? count(rows('48_ACTIONS').filter(r=>field(r,'Status')!=='Done').length) : 'Not recorded','Actual records only','shield','amber'),tile('Decisions',rows('49_DECISIONS').length ? count(rows('49_DECISIONS').length) : 'Not recorded','Board records required','shield','amber'),tile('Owners','Proposed roles','Confirm owners and dates','people'),tile('Next review','No date','Set by the organization','clock','amber')];
    else if (page === 'P7') list = [tile('Current record','Working','Draft management review','document'),tile('Reporting year',fy(S().currentYear),'Source scenario retained','clock'),tile('Open questions',count(S().open),'Travel with every report','document','red'),tile('Files uploaded',count(S().uploadedFiles),'Checksums retained','document'),tile('Checks to review',count(S().checkReview),'Source disagreements visible','shield','amber'),tile('Decisions',count(rows('49_DECISIONS').length),'Recorded decisions only','shield'),tile('External release','Not authorized','Separate approval required','shield','amber')];
    else list = [mt('REVENUE','Operating revenue','Projected','money'),mt('OPEX','Running costs','Projected','document'),mt('NOI','Income after costs','Before loan payments','chart'),mt('DEBT_SERVICE','Loan payments','Principal + interest','bank'),mt('DSCR','Coverage','Income per $1 due','shield'),mt('CASH_SHORTFALL','Shortfall','Cash after loan payments','shield'),mt('RESERVE_CLOSING','Closing reserve','Permitted use unknown','money')];
    return `<div class="tiles">${list.join('')}</div>`;
  }
  function barChart(points, grouped = false, height = 190) {
    const width = 600, left = 12, right = 10;
    const values = points.flatMap(p => grouped ? [p.noi?.value,p.debt?.value] : [p.value]).filter(v=>v!=null);
    const positive = Math.max(0,...values), negative = Math.max(0,...values.map(v=>-v));
    const range = Math.max(1,positive+negative), scale = (height-66)/range;
    const baseline = 24+positive*scale;
    const step = (width-left-right)/Math.max(points.length,1), barWidth = Math.min(36,step*(grouped ? .32 : .64));
    return `<svg class="chart-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="${grouped ? 'Income after costs against annual loan payments' : 'Annual source-plan values'}"><path d="M${left} ${baseline}H${width-right}" stroke="#d5e2ec"/>${points.map((p,i)=>{
      const vals = grouped ? [{...p.noi,color:'#009ba4'}, {...p.debt,color:'#b3cad6'}] : [{...p,color:p.value<0?'#cf4054':'#009ba4'}];
      const x = left+i*step+step/2;
      return vals.map((v,j)=>{
        if(v.value==null)return `<text x="${x}" y="${baseline-8}" text-anchor="middle" fill="#d29100">—</text>`;
        const h=Math.abs(v.value)*scale;const bx=x+(grouped?(j?1:-barWidth-1):-barWidth/2);const by=v.value<0?baseline:baseline-h;
        return `<g data-metric="${esc(v.id||'')}"><rect x="${bx}" y="${by}" width="${barWidth}" height="${Math.max(.6,h)}" rx="2" fill="${v.color}"/><text x="${bx+barWidth/2}" y="${v.value<0?Math.min(height-20,baseline+h+10):by-6}" text-anchor="middle" font-size="${grouped?9:10}" fill="${v.value<0?'#cf4054':'#009ba4'}">${(v.value/1e6).toFixed(grouped?1:2).replace(/\.00$/,'')}</text><title>${esc(p.year)}: ${esc(money(v.value))}</title></g>`;
      }).join('')+`<text x="${x}" y="${height-4}" text-anchor="middle" font-size="10" fill="#183f67">${fy(p.year)}</text>`;
    }).join('')}</svg>`;
  }
  function cashChart(){return barChart(S().displayYears.map(y=>({...at('CASH_AFTER_DEBT',y),year:y})),false,page==='P1'?165:200);}
  function homesChart(){const base=data.homesChart.filter(p=>S().displayYears.includes(p.year));const values=base.filter((p,i,list)=>p.value!=null&&(i===0||p.value!==list[i-1]?.value));const max=Math.max(1,...values.map(p=>p.value));return `<svg class="chart-svg" viewBox="0 0 400 200" role="img" aria-label="Projected homes by fiscal year"><path d="M10 165H390" stroke="#d5e2ec"/>${values.map((p,i)=>{const step=380/values.length,x=10+step*i+step*.2,h=p.value/max*130;return `<g data-metric="${esc(p.id)}"><rect x="${x}" y="${165-h}" width="${step*.6}" height="${h}" rx="3" fill="#009ba4"/><text x="${x+step*.3}" y="${155-h}" text-anchor="middle" fill="#009ba4" font-size="12" font-weight="bold">${count(p.value)}</text><text x="${x+step*.3}" y="190" text-anchor="middle" font-size="11" fill="#173f68">${fy(p.year)}</text></g>`;}).join('')}</svg>`;}
  function donut(value,total,label,color='#009ba4',displayValue=value){const percent=total>0?value/total*100:0;return `<div class="donut-wrap"><div class="donut"><svg viewBox="0 0 120 120" role="img" aria-label="${esc(`${value} of ${total} ${label}`)}"><circle cx="60" cy="60" r="48" fill="none" stroke="#dce7ee" stroke-width="13"/><circle cx="60" cy="60" r="48" fill="none" stroke="${color}" stroke-width="13" stroke-dasharray="${percent*3.016} 301.6"/></svg><div><b>${count(displayValue)}</b><small>${esc(label)}</small></div></div></div>`;}
  function stewardship(two=false){const miss=area=>payload.missing.find(x=>x.area===area);return `<div class="stewardship${two?' two':''}"><article class="mini unknown"><h3>${icon('home')}Affordability</h3><strong>${esc(miss('Affordability')?.state)}</strong><p>${page==='P1'?'Actual rent rolls not received.':'Actual rent rolls and household evidence are needed. New-home rents in the model are assumptions.'}</p></article><article class="mini"><h3>${icon('people')}Mission</h3><strong>${count(S().existingHomes)} existing homes,<br>${count(S().plannedHomes)} planned</strong><p>${page==='P1'?'Occupancy and protections unconfirmed.':'Source-plan homes. Occupancy, residents served and protections remain unconfirmed.'}</p></article><article class="mini unknown"><h3>${icon('shield')}Governance</h3><strong>${esc(miss('Governance')?.state)}</strong><p>${page==='P1'?'Permissions and limits needed.':'Confirm reserve permissions, financing authority and resident protections.'}</p></article><article class="mini"><h3>${icon('building')}Assets</h3><strong>${esc(format(metric('RESERVE_CONTRIBUTION')))}/year</strong><p>${page==='P1'?'Condition needs review.':'Projected repair set-aside. It does not establish repair needs. Condition and capital plan required.'}</p></article></div>`;}
  function proposedActions(){return `<div class="recommendations">${payload.proposals.map(p=>`<article><h3>${esc(p.action)}</h3><strong>${esc(p.size)}</strong><small>${esc(p.owner)}</small><small>${esc(p.timing)}</small><button type="button" data-proposal="${esc(p.id)}">View / record action</button></article>`).join('')}</div>`;}
  function baseline(){return panel('From baseline to outcomes',`<p class="muted">IREI establishes the portfolio baseline, tracks decisions arising from Stage 1, and measures how those decisions affect assets, financial resilience and mission outcomes over time.</p><div class="baseline"><article><strong>1. TODAY · BASELINE</strong><p>Financial position: income, loan payments, reserves<br>Asset condition and capital needs<br>Affordability and resident protections<br>Portfolio risks and evidence gaps</p></article><article><strong>2. DECISIONS</strong><p>Refinance: address liquidity and terms<br>Reinvest / rehabilitate: critical building systems<br>Redevelop / intensify: mission growth<br>Seek subsidy / equity: capital and support</p></article><article><strong>3. FUTURE OUTCOMES</strong><p>Financial resilience and asset quality<br>Homes remain affordable and secure<br>People and households served<br>Long-term community impact: not yet measured</p></article></div>`,'','chart');}
  function solutions(){return panel('We have solutions to test',`<ol class="solutions">${data.solutions.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`,'Choose a funded test pathway. Do not assume reserves are usable or that proposed options are approved.','chart');}
  function capacity(){return panel('Safe borrowing capacity',`<div class="facts"><h3>Property security</h3><p>Current appraisals, balances and title/security review are needed.</p><h3>Ability to repay</h3><p>${esc(format(metric('DSCR')))} this year. ${fy(S().fullYear)} is ${esc(format(metric('DSCR',true)))} in the source plan, ${esc(format(metric('DSCR_EX_PLACEHOLDER',true)))} without placeholder subsidy.</p><h3>Permission and control</h3><p>Reserve use, consents and mission limits remain unconfirmed.</p></div>`,'Borrowing is not yet sized. Refinancing is not free cash.','bank','','capacity');}
  function page1(){return `<div class="grid overview-top">${panel(`What ${data.context.organization} has · and what it means`,['CURRENT-CASH','RENEWAL','COVERAGE-'+S().fullYear,'SUBSIDY'].map(id=>payload.executiveFindings.find(f=>f.id===id)).filter(Boolean).map(f=>`<div class="finding tone-${esc(f.tone)}"><p>${esc(f.meaning)}</p></div>`).join(''),'A current surplus gives time to act. Confirm loan evidence and the subsidy decision before commitments.','shield','','findings')}${panel('Cash after loan payments through the plan',`<p class="chart-title">Full source plan ($M); ${fy(S().currentYear)} is current</p>${cashChart()}`,`Future shortfalls remain visible. Peak annual payments: ${money(S().peak?.value)} in ${fy(S().peak?.year)}.`,'chart','','financial')}${capacity()}</div>`+panel('PORTFOLIO SNAPSHOT',`<div class="snapshot-grid"><div><h3>Buildings by status</h3>${donut(S().operating,S().buildings,'buildings','#009ba4',S().buildings)}<p class="muted">${S().operating} operating / ${S().planned} planned</p></div><div><h3>Homes over time</h3>${homesChart()}</div>${stewardship()}<div><h3>Locations (source model)</h3><div class="city-list">${S().cities.length?S().cities.map(c=>`<div>• ${esc(c)}</div>`).join(''):empty('Locations not established')}</div></div></div>`,'','building','','properties')+baseline()+`<div class="grid two">${solutions()}${panel('Decisions and next actions · proposed',proposedActions(),'Confirm subsidy, close the residual gap, verify terms and prepare a sized fallback. Board approval follows the evidence.','shield','','actions')}</div>`;}
  const historicalRows = property => (payload.historicalProperties || []).filter(r=>field(r,'Property_ID')===property);
  function historicalValue(property,key) {
    const values=[...new Set(historicalRows(property).map(r=>field(r,key)).filter(Boolean))];
    return values.length===1?values[0]:values.length>1?'Conflicting records':'';
  }
  function historicalNote(property) {
    const records=historicalRows(property);
    if(!records.length)return 'Historical summary not mapped; current evidence needs review';
    const dates=[...new Set(records.map(r=>field(r,'Date')).filter(Boolean))];
    return 'Historical support · '+(dates.join('; ')||records.map(r=>field(r,'Source_File')).filter((v,i,a)=>a.indexOf(v)===i).join('; '))+'; current evidence needs review';
  }
  function propertyTable(){return table(['Property / alias','Source class','Historical listed units',fy(S().currentYear)+' source NOI*','Evidence notes'],data.properties.map(p=>{const m=data.buildingMetrics.find(m=>m.scope===p.id&&m.code==='NOI');return [`<button type="button" data-property="${esc(p.id)}">${esc(field(p,'Property_Name'))}</button>`,esc(field(p,'Operating_Status')),esc(historicalValue(p.id,'Units')||field(p,'Total_Units')||'Not supplied'),mb(m),esc(historicalNote(p.id))];}));}
  function page2(){return `<div class="grid three mix-grid">${panel('Portfolio mix',`${donut(S().operating,S().buildings,'buildings','#009ba4',S().buildings)}<p class="donut-caption">${S().operating} operating / ${S().planned} planned</p><p class="muted">${S().planned} planned sites remain in the same portfolio scope.</p>`,'Source classification; occupancy unconfirmed.','building','','properties')}${panel(`Where ${data.context.organization} operates`,S().cities.length?`<div class="city-list">${S().cities.map(c=>esc(c)).join('<br>')}</div>`:empty('No location register supplied'),S().historicalDetailState,'home','','properties')}${panel('Homes by year',`<p class="chart-title">Source-plan homes</p>${homesChart()}`,'','building','','homes')}</div>`+panel('Property register · source dates kept visible',propertyTable(),'Historical unit counts are not current occupied homes. *Source NOI = property revenue less operating costs. Property detail is not added to the portfolio control.','building','','properties')+panel('Mission and stewardship · what we know and what we need',stewardship(),'Growth can support the mission only if occupancy, affordability, agreements and repair needs are confirmed. Protect these before financing decisions.','shield','','mission')+panel('DECISIONS AND NEXT ACTIONS · PROPOSED',`<div class="recommendations">${payload.missing.filter(x=>x.area!=='Loan terms').map(m=>`<article><h3>${esc(m.required)}</h3><strong>${esc(m.state)}</strong><small>${esc(m.unlocks)}</small></article>`).join('')}</div>`,'Keep stable property IDs and aliases. Do not count an address alias as an additional building.','shield','','mission');}
  function outlook(){return table(['Year','Income','Payments','Cash after','Coverage'],S().displayYears.map(y=>[esc(fy(y)),mb(at('NOI',y)),mb(at('DEBT_SERVICE',y)),mb(at('CASH_AFTER_DEBT',y)),mb(at('DSCR',y))]),'small-table');}
  function incomeDebt(){return barChart(S().displayYears.map(year=>({year,noi:at('NOI',year),debt:at('DEBT_SERVICE',year)})),true,215)+`<p class="legend"><span><i class="swatch" style="background:#009ba4"></i>Income after costs</span><span><i class="swatch" style="background:#b3cad6"></i>Loan payments</span></p>`;}
  function revenueMix(){const codes=['REV_RENT_EXISTING','REV_RENT_NEW','REV_SUBSIDY','REV_OTHER'],colors=['#009ba4','#47b5bb','#d9940a','#0b3158'],names=['Existing-home rent','New-home rent','BC Housing subsidy','Other income'];return [false,true].map(full=>{const total=metric('REVENUE',full)?.value;return `<p class="chart-title">${fy(full?S().fullYear:S().currentYear)} ${full?'full-operation source plan':'current projection'} · ${esc(money(total))}</p><svg class="chart-svg" viewBox="0 0 400 60" role="img" aria-label="Revenue composition">${codes.map((code,i)=>{const m=metric(code,full),previous=codes.slice(0,i).reduce((n,c)=>n+(metric(c,full)?.value||0),0);return m?.value==null||!total?'':`<g data-metric="${esc(m.id)}"><rect x="${previous/total*400}" y="5" width="${m.value/total*400}" height="45" fill="${colors[i]}"/><title>${names[i]}: ${esc(money(m.value))}</title>${m.value/total>.1?`<text x="${(previous+m.value/2)/total*400}" y="32" text-anchor="middle" fill="white" font-size="12" font-weight="bold">${(m.value/1e6).toFixed(2)}</text>`:''}</g>`;}).join('')}</svg><div class="legend">${codes.map((code,i)=>`<span><i class="swatch" style="background:${colors[i]}"></i>${names[i]}<br><b>${esc(format(metric(code,full)))}</b></span>`).join('')}</div>`;}).join('<div style="height:20px"></div>');}
  function financialOptionsTable(){return table(['Option to test','Size','Effect / limit'],payload.options.slice(0,4).map(o=>[esc(o.name),esc(o.amount),esc(o.protects)+'; '+esc(o.needs)]));}
  function optionsTable(){return table(['Option','Amount','Needs first','What it protects','What it risks'],payload.options.map(o=>[esc(o.name),esc(o.amount),esc(o.needs),esc(o.protects),esc(o.risks)]));}
  function sensitivity(){return panel(`${fy(S().fullYear)} subsidy sensitivity · the decision the board must see`,table(['Case','Income after costs','Payments','Cash shortfall','Coverage'],[['Source plan',mb(metric('NOI',true)),mb(metric('DEBT_SERVICE',true)),mb(metric('CASH_SHORTFALL',true)),mb(metric('DSCR',true))],['Without placeholder subsidy',mb(metric('NOI_EX_PLACEHOLDER',true)),mb(metric('DEBT_SERVICE',true)),mb(metric('SHORTFALL_EX_PLACEHOLDER',true)),mb(metric('DSCR_EX_PLACEHOLDER',true))]]),'Sensitivity subtracts only source-labeled placeholder subsidy. Costs and loan payments are unchanged; no mitigation is assumed.','chart','','sensitivity');}
  function page3(){return `<div class="grid financial">${panel('Income against loan payments',incomeDebt()+outlook(),'','chart','','financial')}${panel('Where the money comes from',revenueMix(),`${fy(S().fullYear)} includes ${F().placeholderAnnual}/year of source-labeled placeholder subsidy. Confirm it before relying on the plan.`,'money','','revenue')}</div><div class="grid financial">${panel('Financial options · sized to cash need',financialOptionsTable(),`Cash need and target cushion are separate. The ${F().target} target requires ${format(metric('COVERAGE_GAP',true))} additional NOI in the source plan and ${format(metric('COVERAGE_GAP_EX_PLACEHOLDER',true))} without placeholder subsidy.`,'bank','','options')}${panel('Mission and stewardship',stewardship(true),'','shield','','mission')}</div><div class="grid three risk-grid">${panel('Principal financial risks',payload.findings.filter(f=>f.tone!=='green').map(f=>`<div class="finding tone-${esc(f.tone)}"><p>${esc(f.meaning)}</p></div>`).join(''),'','shield','','findings')}${panel('Loans and near-term maturities',`<div class="facts"><h3>Loan payments now</h3><p>${esc(format(metric('DEBT_SERVICE')))} in ${fy(S().currentYear)}</p><h3>Peak annual payments</h3><p>${esc(money(S().peak?.value))} in ${fy(S().peak?.year)}</p><h3>New development payments</h3><p>${esc(F().newPayments)}/year at full operation. These are annual payments, not principal balances.</p><h3>Maturity records</h3><p>${esc(data.maturities.state)}. Obtain current lender terms; a renewal-year selector is not a loan maturity record.</p></div>`,'','bank','','maturities')}${panel('Reserve balance by year',`<p class="chart-title">Closing source-plan balances ($M)</p>${barChart(S().displayYears.map(y=>({...at('RESERVE_CLOSING',y),year:y})),false,240)}`,`Current closing reserve: ${format(metric('RESERVE_CLOSING'))}. Permitted use is unknown. Opening resets need reconciliation.`,'money','','reserve')}</div>`+panel('Building detail · available behind View details',`<p>${S().buildings} source rows; payment reconciliation and sign questions remain visible. Select a building to inspect its financial and evidence record.</p>`, 'Building coverage is not validated simply because a portfolio coverage ratio is available.','building','','properties')+sensitivity()+panel('DECISIONS AND NEXT ACTIONS · PROPOSED',proposedActions(),'','shield','','actions');}
  function evidenceAreas(){return table(['Area','State'],[['Revenue / costs',esc(metric('NOI')?.displayState||'No data')],['Loan payments','Partly confirmed; terms unverified'],['Reserve','Use unknown'],['Properties','Source working register'],...payload.missing.map(m=>[esc(m.area),esc(m.state)])],'small-table');}
  function questionTable(){return table(['Exception ID','Question','Why it matters','Who answers*','Status'],data.openQuestions.map(r=>[`<button type="button" data-record="${esc(r.id)}" data-sheet="51_EXCEPTIONS">${esc(r.id)}</button>`,esc(field(r,'Plain_Question')||field(r,'Question_For_Client')||field(r,'Exception_Type')||field(r,'Issue_Type')),esc(field(r,'Why_It_Matters')||field(r,'Description')),esc(field(r,'Who_Answers')||field(r,'Suggested_Respondent')||'CFO / management'),esc(field(r,'Status'))]));}
  function page4(){return `<div class="grid three evidence-top">${panel('Evidence by area',evidenceAreas(),'Source figures are available. Current-year actuals and transaction evidence remain incomplete.','document','','checks')}${panel(`Questions for ${data.context.organization}`,`${donut(S().open,S().exceptionTotal,'open of '+S().exceptionTotal+' records','#cd3d50')}<p class="donut-caption" style="color:var(--teal);text-align:center">${S().resolved} resolved + ${S().accepted} accepted</p>`,'Keep the register status. Supporting records do not automatically close gaps.','document','','questions')}${panel('What the record supports',`<div class="facts"><p>✓ ${fy(S().currentYear)} source financial projections and the configured horizon.</p><p>✓ ${count(metric('HOMES_TOTAL')?.value)} projected homes and ${S().buildings} working building records.</p><p>✓ Uploaded sources and numeric cell references remain traceable.</p><p>Not confirmed: actual occupied homes, current renewals, reserve permissions or placeholder subsidy.</p></div>`,'The board can choose what to test. Financing approval needs the missing records.','shield','','sources')}</div>`+panel(`Open questions for ${data.context.organization} · ${S().open} records`,questionTable(),'*Roles are proposed review owners. Resolved and accepted records remain distinct from open questions.','document','questions-panel','questions')+panel('Provide this · and we can tell you that',table(['Provide','What it unlocks'],[['Current loan / renewal statements','Current balances, terms, rates and renewal outcomes'],['Written project subsidy commitments',`Whether the ${F().placeholderAnnual}/year source assumption is secured`],['Reserve policy and bank reconciliation','Permitted use, minimum cash floor and opening resets'],...payload.missing.filter(m=>m.area!=='Loan terms').map(m=>[esc(m.required),esc(m.unlocks)])]),'Ask first for documents that can change the decision: lender statements, subsidy confirmation and reserve permissions.','document','','mission')+`<div class="grid two">${panel('Evidence risks','<p>Source terms may already have changed.</p><p>Placeholder subsidy is not committed revenue.</p><p>Unreconciled payment signs and totals prevent reliable building coverage.</p><p>Rent assumptions are not actual rent rolls.</p>','','shield','','checks')}${panel('How to close the gaps','<p>Start with the organization’s statements, commitments, policy and rent rolls.</p><p>Obtain appraisals, title review and condition reports where needed.</p><p>Record the document, date, reviewer and affected exception before changing its status.</p>','','document','','sources')}</div>`+panel('DECISIONS AND NEXT ACTIONS · PROPOSED',proposedActions(),'The evidence process leads to a choice: fund the confirmed plan or activate a sized fallback.','shield','','actions');}
  function stagePath(){const year=S().currentYear,full=S().fullYear;return `<div class="stage-grid"><article class="stage"><h3>MORTGAGE TERMS · VERIFY NOW</h3><strong>Terms not established</strong><b>Where we stand</b><p>Source payment schedules exist; current instruments and renewal outcomes are missing.</p><b>The issue</b><p>Model timing does not establish lender maturity dates.</p><b>Options</b><p>Verify current outcomes, then obtain priced renewal scenarios.</p><b>To confirm</b><p>Current lender statements, balances and approved terms.</p></article><article class="stage"><h3>THIS YEAR · ${fy(year)}</h3><strong>${esc(format(metric('CASH_AFTER_DEBT')))} source cash</strong><b>Where we stand</b><p>Revenue ${esc(format(metric('REVENUE')))}; costs ${esc(format(metric('OPEX')))}; payments ${esc(format(metric('DEBT_SERVICE')))}.</p><b>The issue</b><p>Source projections are not confirmed actual cash or occupied homes.</p><b>What covers it</b><p>Source-plan income after costs; closing reserve ${esc(format(metric('RESERVE_CLOSING')))} has unconfirmed permitted use.</p><b>To confirm</b><p>Actual financial results, occupancy and cash restrictions.</p></article><article class="stage"><h3>BUILD-UP · SOURCE HORIZON</h3><strong>${count(S().plannedHomes)} homes planned</strong><b>Where we stand</b><p>${S().planned} planned properties; source homes grow from ${count(S().existingHomes)} to ${count(S().plannedHomes)}.</p><b>The issue</b><p>Timing, costs and subsidy affect delivery and cash.</p><b>Options</b><p>Track milestones; test delays and funding terms before commitments.</p><b>To confirm</b><p>Delivery dates, costs, occupied homes and committed subsidy.</p></article><article class="stage"><h3>FULL OPERATIONS · ${fy(full)}</h3><strong>${esc(format(metric('DSCR',true)))}; ${esc(format(metric('CASH_AFTER_DEBT',true)))}</strong><b>The issue</b><p>Remove placeholder subsidy: ${esc(F().fallbackAnnual)} shortfall; ${esc(format(metric('DSCR_EX_PLACEHOLDER',true)))} coverage.</p><b>What covers it</b><p>Confirmed ${esc(F().placeholderAnnual)}/year support plus ${esc(F().residualAnnual)} residual relief in the source plan.</p><b>Options</b><p>Confirm subsidy first; prepare a recurring fallback or a permitted one-year bridge.</p><b>To confirm</b><p>Funding term, payment relief and mission protections.</p></article></div>`;}
  function page5(){return panel('Four-stage path · where we stand and what to decide',stagePath(),'Lead with actual loan evidence. A configured renewal year remains an unverified planning selector.','clock','','maturities')+panel(`What ${data.context.organization} is already doing`,rows('48_ACTIONS').length?actualActions():empty('No management actions are recorded. Proposed review actions are shown separately.'),'','shield','','actions')+panel('Risks compared · size, date and response',table(['Risk','Size / interpretation','When','What would settle it'],payload.findings.filter(f=>f.tone!=='green').map(f=>[esc(f.title),esc(f.meaning),f.id.startsWith('COVERAGE-')?esc(f.id.slice(9)):f.id==='SUBSIDY'?esc(S().fullYear):'Before commitments',esc(f.evidenceNeeded)])),'A confirmed bridge funds a year. A recurring solution changes the operating gap. Board decisions and approval conditions remain explicit.','shield','','findings')+panel('What the risks mean for mission and stewardship',stewardship(),'Every solution must state what it protects, what it risks and what approval it needs. Affordability and reserve floors are board constraints.','shield','','mission')+panel(`Options compared · sized to ${fy(S().fullYear)} cash need`,optionsTable(),'First option to test: confirm subsidy plus residual cash relief. Keep a sized no-subsidy fallback. No reserve or financing amount is approved.','chart','','options')+panel('DECISIONS AND NEXT ACTIONS · PROPOSED',proposedActions(),'Start with the least disruptive recurring pathway, verify terms and retain a funded fallback with mission and cash-floor protections.','shield','','actions');}
  function actualActions(){return table(['Action','Owner','Due date','Status','Origin'],rows('48_ACTIONS').map(r=>[esc(field(r,'Action_Text')||field(r,'Short_Title')),esc(field(r,'Owner_Name')||field(r,'Owner_Role')||'Unassigned'),esc(field(r,'Due_Date')||'No date'),esc(field(r,'Status')),esc(field(r,'Finding_ID')||field(r,'Linked_Exception_IDs'))]));}
  function page6(){const prior=data.financialOutlook.filter(p=>p.year<S().currentYear).at(-1);return `<div class="grid two review-top">${panel('What changed in this review',`<div class="facts"><h3>Before · prior source period</h3><p>${prior?`${fy(prior.year)}: ${format(at('CASH_AFTER_DEBT',prior.year))} cash after loans; ${format(at('DSCR',prior.year))} coverage.`:'No prior comparison available.'} This compares source periods, not an observed outcome.</p><h3>After · current source period</h3><p>${fy(S().currentYear)}: ${esc(format(metric('CASH_AFTER_DEBT')))} cash after loans, ${esc(format(metric('DSCR')))} coverage and ${esc(format(metric('RESERVE_CLOSING')))} closing reserve.</p><h3>Priority review</h3><p>Current lender terms; ${fy(S().fullYear)} ${esc(format(metric('DSCR',true)))} coverage; no-subsidy gap ${esc(F().fallbackAnnual)}.</p></div>`,'','document','','financial')}${panel('What changes the conclusion',`<p>Renewal statements: verify current terms and future exposure.</p><p>Subsidy commitment: determines whether the source plan or ${esc(F().fallbackAnnual)} fallback is needed.</p><p>Reserve policy: establishes usable bridge capacity and minimum cash floor.</p><p>Rent rolls and condition reports: establish mission and repair constraints.</p>`,'','chart','','mission')}</div>`+panel('Proposed action tracker · confirm owners and dates',table(['Action','Proposed owner','Timing trigger','Status'],payload.proposedTracker.map(p=>[`<button data-proposal="${esc(p.id)}" type="button">${esc(p.action)}</button>`,esc(p.owner),esc(p.timing),'Proposed'])),'These are proposed review actions. Record the owner, date, evidence and decision when the organization acts.','document','','actions')+ (rows('48_ACTIONS').length ? panel('Management actions on record',actualActions(),'Proposed analysis does not silently populate the management register.','document','','actions') : '') +panel('Change log · review revisions',data.events.length?table(['Date','Change','Effect / reason'],data.events.map(e=>[esc(e.date.slice(0,10)),esc(e.kind),esc(e.reason)])):empty('No revisions recorded after this upload. The original dated baseline is retained.'),'','document','','sources')+`<div class="grid two">${panel('Decisions on record',rows('49_DECISIONS').length?table(['Decision','Date','Status'],rows('49_DECISIONS').map(r=>[esc(field(r,'Decision_Text')),esc(field(r,'Decision_Date')),esc(field(r,'Decision_Status'))])):empty('No data available'),'The board decision, evidence, owner, date and outcome must be recorded. Proposals do not count as approvals.','shield','','actions')}${panel('Review cycle','<p>Monthly: review actions and evidence.</p><p>Quarterly: refresh financial inputs and projections.</p><p>Annually: complete the full review.</p><p>On an event: refresh mortgage renewal, subsidy, project delay and major capital scenarios.</p>','Proposed review cadence; confirm it with the organization.','clock','','actions')}</div>`+note('Request priority documents, confirm proposed owners and dates, and test the selected pathway. Record decisions and release authorization separately.');}
  function page7(){return panel('A presentation that keeps the evidence visible',`<div class="report-pathways">${[['Board summary','Seven decision views with source figures, sized options and unresolved questions.'],['Management action list','Proposed review tasks alongside actual recorded owners and dates.'],['Funder submission','Working evidence package. Missing information and authorization remain explicit.'],['Lender package','Cash-flow and sensitivity screen. Current terms and security still required.']].map(([title,description])=>`<article><h3>${title}</h3><strong>Internal draft · management review</strong><p>${description}</p></article>`).join('')}</div><div class="buttons" style="margin-top:20px"><button type="button" id="print-all" class="primary">Print all pages / Save PDF</button><button type="button" id="download-data">Download analysis record</button></div>`,'Reports retain source identity, assumptions, review states and unresolved questions. An internal draft is not a financing approval or an authorized external release.','document','','sources')+panel('Automatic checks · what the data exposed',`<p>${S().checkPass} pass · ${S().checkReview} need review · ${S().checkMissing} cannot be tested from the available data.</p>${checksTable(payload.checks.filter(c=>c.state!=='Pass').slice(0,12))}`,'Checks compare source controls and mapped records. A pass does not mean that the evidence is audited or that a financing decision is approved.','shield','','checks')+panel('Interactive option test',`<form id="option-form" class="option-form"><label>Fiscal year<select name="year">${data.financialOutlook.map(y=>`<option ${y.year===S().fullYear?'selected':''}>${esc(y.year)}</option>`).join('')}</select></label><label>Case<select name="case"><option>Without placeholder</option><option>Base</option></select></label><label>Option<select name="kind"><option>Bridge</option><option>Recurring income</option><option>Payment relief</option></select></label><label>Annual benefit / one-year cash<input name="amount" type="number" min="0" step="0.01" required></label><label>Added annual debt service<input name="additionalDebtService" type="number" min="0" value="0" step="0.01"></label><button class="primary">Test option</button></form><div id="option-result" style="margin-top:20px"></div>`,'A bridge funds one year; it does not improve operating coverage. Recurring income and payment relief are different tests. Results are screening calculations, not commitments.','chart','','options')+panel('Source identity and traceability',sourcesTable(),'Original workbooks are retained with their checksums. New uploads create new records; they do not overwrite this baseline.','document','','sources');}
  function sourcesTable(){return table(['Uploaded source','Role','SHA-256'],payload.sources.map(s=>[esc(s.name),esc(s.kind),`<span class="break">${esc(s.sha256)}</span>`]));}
  function checksTable(checks){return table(['Check','Period','Expected','Observed','Difference','State'],checks.map(c=>[esc(c.area),esc(c.period),esc(c.expected==null?'Not available':Number(c.expected).toLocaleString('en-CA',{maximumFractionDigits:2})),esc(c.observed==null?'Not available':Number(c.observed).toLocaleString('en-CA',{maximumFractionDigits:2})),esc(c.difference==null?'Not testable':Number(c.difference).toLocaleString('en-CA',{maximumFractionDigits:2})),esc(c.state)]));}
  const renderers=[page1,page2,page3,page4,page5,page6,page7];
  function draw(){if(!data)return;document.body.className=`page-${page}${document.body.classList.contains('presentation')?' presentation':''}`;$('page-title').textContent=titles[Number(page[1])-1];$('organization-name-display').textContent=data.context.organization+' Portfolio (Pilot)';$('organization-chip').textContent=data.context.organization+' PORTFOLIO';$('source-context').textContent=`FY${S().currentYear} · ${metric('NOI')?.scenario||'Source plan'} | ${data.context.sourceVersion||'Uploaded source'} | Historical supporting records retain source dates`; $('source-context').title='Controlling workbook: '+(payload.controllingSource?.name||'Uploaded assessment')+' · assessment '+data.context.id;$('content').innerHTML=tiles()+renderers[Number(page[1])-1]();$('source-footer').textContent='Source: '+payload.sources.map(s=>s.name).join('; ')+'. Original record states and dates retained.';$('page-nav').querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+page));$('year').innerHTML=data.financialOutlook.map(y=>`<option ${y.year===S().currentYear?'selected':''}>${esc(y.year)}</option>`).join('');$('year-control').hidden=false;$('present').hidden=false;}
  // V2 deliberately operates without portal sign-in or session confirmation.
  async function authorizedFetch(url, options = {}) {
    return fetch(url, { ...options, credentials: 'omit' });
  }
  async function api(path,options={}){busyCount++;document.body.setAttribute('aria-busy','true');$('loading-bar').hidden=false;try{const r=await authorizedFetch('/api/submissions/board/'+path,options);const type=r.headers.get('content-type')||'';const body=type.includes('json')?await r.json():await r.text();if(!r.ok){const e=Error(body?.error||body?.detail||`Request failed (${r.status}).`);e.status=r.status;throw e;}return body;}finally{busyCount--;document.body.setAttribute('aria-busy',String(busyCount>0));$('loading-bar').hidden=busyCount===0;}}
  const json=(body,method='POST')=>({method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
  async function load(){payload=await api(`assessments/${encodeURIComponent(id)}`);data=payload.view;draw();}
  function openDetail(title,body){$('detail-title').textContent=title;$('detail-body').innerHTML=body;$('detail-dialog').showModal();}
  async function metricDetails(metricId){if(!metricId)return;try{const r=await api(`assessments/${encodeURIComponent(id)}/metrics/${encodeURIComponent(metricId)}`);openDetail(r.metric.code+' · '+r.metric.year,`<p><b>${esc(format(r.metric))}</b> · ${esc(r.metric.displayState)} · ${esc(r.metric.reviewState)}</p><p>${esc(r.explanation)}</p><p>Calculation: ${esc(r.metric.calcId)} / ${esc(r.metric.calcVersion)}</p>`+table(['Input','Source value','State / review','Original source cell','Formula / lineage'],r.facts.map(f=>[esc(f.code),esc(f.value==null?'No data available':String(f.value)),esc(f.valueState+' / '+f.reviewStatus),esc(f.sourceLocation),`<span class="break">${esc(f.formula)}<br>${f.inputCells.map(esc).join('<br>')}</span>`]))+sourcesTable());}catch(e){$('notice').textContent=e.message;}}
  function propertyDetails(propertyId){const p=data.properties.find(p=>p.id===propertyId);if(!p)return;openDetail(field(p,'Property_Name'),table(['Field','Source record'],Object.entries(p.fields).map(([k,v])=>[esc(k.replaceAll('_',' ')),esc(v)]))+table(['Year','Revenue','Operating costs','NOI','Loan payments','Coverage'],data.financialOutlook.map(y=>{const m=code=>data.buildingMetrics.find(m=>m.scope===propertyId&&m.year===y.year&&m.code===code);const allCurrent=y.year===S().currentYear;return allCurrent?[esc(y.year),mb(m('REVENUE')),mb(m('OPEX')),mb(m('NOI')),mb(m('DEBT_SERVICE')),mb(m('DSCR'))]:null;}).filter(Boolean))+table(['Historical field','Source observation','Original cell'],historicalRows(propertyId).flatMap(r=>['Units','City','Address','Maturity','Balance','Date'].filter(k=>field(r,k)).map(k=>[esc(k),esc(field(r,k)),esc(field(r,'Source_File')+' · '+field(r,k+'_Source'))])))+note('Portfolio results use their own controls. Building payments need an instrument-to-property reconciliation before coverage is relied on.'));}
  function openProposal(proposalId){const p=[...payload.proposals,...payload.proposedTracker].find(p=>p.id===proposalId);if(!p)return;const form=$('action-form');form.elements.text.value=p.action;form.elements.owner.value='';form.elements.basis.value=p.basis;form.elements.status.value='Proposed';form.elements.dueDate.value='';$('action-error').textContent='';$('action-dialog').showModal();}
  function detail(name){if(name==='properties'){openDetail('Property register and building drill-through',propertyTable()+note(S().historicalDetailState));return;}if(name==='questions'){openDetail('Exception register',questionTable());return;}if(name==='checks'){openDetail('Source checks and reconciliation',`<p>${S().checkPass} pass; ${S().checkReview} need review; ${S().checkMissing} not testable.</p>`+table(['Area','Period','State','Difference','Explanation','Source'],payload.checks.map(c=>[esc(c.area),esc(c.period),esc(c.state),esc(c.difference==null?'Not testable':String(c.difference)),esc(c.explanation),`<span class="break">${esc(c.source)}</span>`])));return;}if(name==='sources'){openDetail('Source records, methods and baseline',sourcesTable()+table(['Supporting property','Units','City','Maturity','Balance','Source date / file'],(payload.historicalProperties||[]).map(r=>[esc(field(r,'Source_Label')),esc(field(r,'Units')),esc(field(r,'City')),esc(field(r,'Maturity')),esc(field(r,'Balance')),esc(field(r,'Date')+' · '+field(r,'Source_File'))]))+table(['Source finding'],data.importFindings.map(f=>[esc(f)]))+note('Baseline '+(data.baseline?.period||S().currentYear)+'; outcomes '+data.outcomeState));return;}if(name==='capacity'){openDetail('Capacity tests',table(['Test','Screen'],[['Property security',esc(money(data.capacity.propertySecurity))],['Ability to repay',esc(money(data.capacity.abilityToRepay))],['Permission',data.capacity.permission==null?'No data available':esc(data.capacity.permission)],['Liquidity above floor',esc(money(data.capacity.liquidity))],['Preliminary safe borrowing',esc(money(data.capacity.preliminarySafeBorrowing))]])+note(data.capacity.note));return;}if(name==='actions'){openDetail('Proposed and recorded actions',proposedActions()+actualActions()+note('Only deliberately recorded actions appear in the management register. Proposed analysis does not constitute approval.'));return;}if(name==='maturities'){openDetail('Loan instruments and maturity evidence',table(['Instrument','Balance date','Balance','Maturity','Review','Source'],rows('33_DEBT').map(r=>[esc(r.id),esc(field(r,'Balance_As_Of')||'Not established'),esc(field(r,'Outstanding_Principal')||'Not established'),esc(field(r,'Maturity_Date')||'Not established'),esc(field(r,'Review_Status')),esc(field(r,'Source_Location'))]))+note(data.maturities.state));return;}if(name==='mission'){openDetail('Mission evidence required',table(['Area','Current state','Provide','What it unlocks'],payload.missing.map(m=>[esc(m.area),esc(m.state),esc(m.required),esc(m.unlocks)])));return;}if(name==='reserve'){openDetail('Reserve opening continuity',checksTable(payload.checks.filter(c=>c.area==='Reserve opening continuity'))+note('A closing reserve is not permission to spend it. Obtain a reserve policy and minimum floor.'));return;}if(name==='options'){openDetail('Options and assumptions',optionsTable()+note('These are sized screening pathways, not approved financing terms.'));return;}if(name==='financial'||name==='revenue'||name==='sensitivity'||name==='homes'){openDetail('Financial source results',outlook()+sensitivity());return;}openDetail('What the analysis exposed',table(['Finding','Meaning','Evidence needed'],payload.findings.map(f=>[esc(f.title),esc(f.meaning),esc(f.evidenceNeeded)])));}
  $('page-nav').innerHTML=labels.map((label,i)=>`<a href="#P${i+1}" class="${page==='P'+(i+1)?'active':''}">${icon(['home','building','chart','document','shield','clock','document'][i])}${esc(label)}</a>`).join('');
  window.addEventListener('hashchange',()=>{if(/^#P[1-7]$/.test(location.hash)){page=location.hash.slice(1);draw();window.scrollTo(0,0);}});
  $('open-upload').onclick=()=>{$('upload-error').textContent='';$('upload-dialog').showModal();};
  $('close-upload').onclick=$('cancel-upload').onclick=()=>$('upload-dialog').close();
  $('file-input').onchange=()=>{$('selected-file').textContent=[...$('file-input').files].map(f=>f.name).join(' · ')||'1–5 files · 50 MB total';};
  $('upload-form').onsubmit=async e=>{e.preventDefault();const b=$('submit-upload');b.disabled=true;b.textContent='Analyzing…';$('upload-error').textContent='';try{const files=[...$('file-input').files];if(!files.length||files.length>5||files.some(f=>!f.name.toLowerCase().endsWith('.xlsx'))||files.reduce((n,f)=>n+f.size,0)>50*1024*1024)throw Error('Choose 1–5 Excel .xlsx files, up to 50 MB in total.');const result=await api('assessments',{method:'POST',body:new FormData(e.target)});id=result.id;localStorage.setItem('irei:boardAssessment',id);const url=new URL(location.href);url.searchParams.set('assessment',id);url.hash='P1';history.replaceState(null,'',url);page='P1';await load();$('upload-dialog').close();e.target.reset();$('selected-file').textContent='1–5 files · 50 MB total';$('notice').textContent='';}catch(err){$('upload-error').textContent=err.message;}finally{b.disabled=false;b.textContent='Process workbooks';}};
  $('year').onchange=async e=>{try{payload=await api(`assessments/${id}/configuration`,json({currentYear:e.target.value,expectedVersion:data.context.version},'PUT'));data=payload.view;draw();}catch(err){$('notice').textContent=err.message;}};
  $('action-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button.primary');b.disabled=true;try{payload=await api(`assessments/${id}/actions`,json({...Object.fromEntries(new FormData(e.target)),expectedVersion:data.context.version}));data=payload.view;$('action-dialog').close();draw();}catch(err){$('action-error').textContent=err.message;}finally{b.disabled=false;}};
  $('present').onclick=()=>{document.body.classList.toggle('presentation');};
  document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('presentation');});
  if(new URLSearchParams(location.search).get('present')==='1')document.body.classList.add('presentation');
  document.addEventListener('click',e=>{const close=e.target.closest('[data-close]');if(close){close.closest('dialog').close();return;}const m=e.target.closest('[data-metric]');if(m){metricDetails(m.dataset.metric);return;}const p=e.target.closest('[data-property]');if(p){propertyDetails(p.dataset.property);return;}const proposal=e.target.closest('[data-proposal]');if(proposal){openProposal(proposal.dataset.proposal);return;}const record=e.target.closest('[data-record]');if(record){const r=rows(record.dataset.sheet).find(r=>r.id===record.dataset.record);if(r)openDetail(r.id,table(['Field','Recorded value'],Object.entries(r.fields).map(([k,v])=>[esc(k),esc(v)])));return;}const d=e.target.closest('[data-detail]');if(d){detail(d.dataset.detail);return;}if(e.target.closest('#download-data')){const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='IREI-board-analysis-'+id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}if(e.target.closest('#print-all'))printAll();});
  document.addEventListener('submit',async e=>{if(e.target.id!=='option-form')return;e.preventDefault();const form=Object.fromEntries(new FormData(e.target));try{const r=await api(`assessments/${id}/options/test`,json({...form,amount:Number(form.amount),additionalDebtService:Number(form.additionalDebtService),subsidyConfirmed:false}));$('option-result').innerHTML=table(['Cash need before','Cash funded','Residual cash need','Coverage after'],[[esc(money(r.cashShortfall)),esc(money(r.cashShortfallFunded)),esc(money(r.residualCashShortfall)),esc(ratio(r.coverageAfter))]])+note(r.note);}catch(err){$('option-result').textContent=err.message;}});
  function printAll(){const saved=page;let report='';for(let i=1;i<=7;i++){page='P'+i;report+=`<section class="report-page page-P${i}"><main><header><div><h1>${titles[i-1]}</h1><h2>${esc(data.context.organization)} Portfolio (Pilot)</h2><p>${esc(S().currentYear)} · source states retained</p></div><div class="badge">INTERNAL DRAFT<small>Not a financing approval</small></div></header>${tiles()}${renderers[i-1]()}<footer class="page-footer">Source: ${payload.sources.map(s=>esc(s.name)).join('; ')}. ${S().open} open questions retained. For discussion purposes only.</footer></main></section>`;}page=saved;$('print-report').innerHTML=report;document.body.classList.add('print-all');window.print();}
  window.addEventListener('afterprint',()=>{document.body.classList.remove('print-all');$('print-report').replaceChildren();});
  if(id)load().catch(err=>{if(err.status===404){localStorage.removeItem('irei:boardAssessment');id='';}$('notice').textContent=err.message;});
})();
